/**
 * FIX-PARTS RESOLVER — turn a known issue's fix into a buyable part with verified links.
 *
 *   Workflow({ scriptPath: 'scripts/_wf-fixparts-resolver.js' })
 *
 * Third pipeline stage. Runs ONLY over already-published, already-verified issues, so it cannot
 * corrupt the research — worst case a part fails verification and the issue keeps its empty
 * fixParts. Targets chosen by scripts/_prep-fixparts-targets.js (recall-derived issues excluded:
 * their remedy is a free dealer repair and must never carry a buy link).
 *
 * REQUIRES WEBSEARCH. Unlike the recall waves, the evidence is not in hand — the whole job is
 * finding the real part and a real product page. Do not run this with an exhausted search budget:
 * agents will fall back to WebFetch, reach only fetchable hosts, and the failure mode is
 * *synthesised* links, which is exactly what must never ship.
 *
 * THE STANDARD (Devon's three pillars): accuracy, no-404 deep links, consistency.
 *  - Fitment-gated: a part number must match THIS make/model/year/engine. Cross-engine part
 *    numbers have silently produced wrong parts before (see the spec-DB audit).
 *  - Never synthesise a URL. Only product pages actually found in search results.
 *  - Better empty than wrong: an unresolved issue keeps empty fixParts and costs nothing.
 *
 * Output feeds scripts/_verify-buylinks.js (zero-AI liveness + soft-404 gate) BEFORE any DB write.
 */
export const meta = {
  name: 'fixparts-resolver',
  description: 'Resolve published issues to a buyable part: OEM PN, aftermarket cross-refs, price range, verified buy links',
  phases: [
    { title: 'Resolve' },
    { title: 'Verify' },
  ],
}

const TARGETS = [{"id":"cadillac-xt6-auto-stop-2020","make":"Cadillac","model":"XT6","years":[2020,2021,2022,2023,2024,2025],"trims":[],"engines":[],"title":"Auto Start-Stop Harshness and Battery Issues","description":"The auto start-stop system engages and disengages harshly, causing the vehicle to shudder on restart. The AGM battery required for the system degrades quickly, and when it weakens, the start-stop system becomes erratic or disables itself. Many owners find the system intrusive.","solution":"Replace the AGM battery with a fresh ACDelco unit if the system is not functioning properly. Have the battery monitor sensor reset after replacement. GM has released recalibrations to improve start-stop smoothness. Aftermarket start-stop eliminator modules are available for owners who want to permanently disable the feature."},{"id":"subaru-forester-head-gasket-1998","make":"Subaru","model":"Forester","years":[1998,1999,2000,2001,2002,2003,2004,2005,2006,2007,2008,2009,2010],"trims":[],"engines":["EJ25"],"title":"EJ25 Head Gasket Failure (External Leak)","description":"The EJ25 2.5L horizontally-opposed engine in 1998-2010 Foresters is notorious for external head gasket failure. Unlike typical blown head gaskets that cause overheating, the Subaru EJ25 gaskets fail externally, leaking coolant and oil down the sides of the engine. The failure is caused by the gasket material (composite) breaking down over time, combined with the horizontal orientation placing uneven stress on the gas","solution":"Replace both head gaskets with the updated MLS (multi-layer steel) gaskets. Resurface both cylinder heads to ensure flatness within spec (0.002\" max). Replace thermostat, water pump, timing belt, and all idler/tensioner pulleys while the engine is apart — these are all accessible during the job. Use genuine Subaru coolant (SOA868V9210). Budget 10-14 hours labor for a boxer engine head gasket job."},{"id":"subaru-forester-premature-front-rear-wheel-bearing-hub-failure","make":"Subaru","model":"Forester","years":[2009,2010,2011,2012,2013,2014,2015,2016,2017,2018],"trims":["Base","Premium","Limited","Touring","X","XT"],"engines":["EJ25","FB25","FA20DIT"],"title":"Premature Front and Rear Wheel Bearing/Hub Failure (Faulty Backing Plate Design)","description":"Forester wheel bearings (both front and rear hub assemblies) fail prematurely, often well before 100,000 miles. The most consistent symptom is a low-pitched grinding, humming or 'airplane' droning noise from the affected corner that grows louder with speed; rear bearing wear is often felt as a vibration under the seats. The noise typically changes pitch or volume during a left/right lane-change maneuver (which distin","solution":"Diagnose by lifting the wheel and checking for play/roughness, and by listening for a noise that changes during gentle S-turns at 30-65 mph. The fix is replacement of the complete wheel hub/bearing assembly (sold as a unit). On 2014-2018 Foresters the front complete hub unit is OEM 28473FL040 (supersedes 28473FJ000/28473FJ020); reuse a new self-locking axle nut and torque to spec. Have an alignment checked, as poor alignment and unbalanced tires accelerate bearing failure. Replacing in pairs is common practice."},{"id":"subaru-forester-ignition-coil-failure-causing-misfire-hard-cold-weather-star","make":"Subaru","model":"Forester","years":[2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022],"trims":["Base","Premium","Limited","Touring","Sport"],"engines":["EJ25","FB25"],"title":"Ignition Coil Failure Causing Misfire and Hard Cold-Weather Starting","description":"Coil-on-plug ignition coils on the Forester are a common failure point. As the coil's internal epoxy/resin cracks with heat and age, the coil produces erratic or insufficient spark, causing single-cylinder misfires, rough idle, hesitation on acceleration, reduced fuel economy and a flashing/steady check-engine light. A frequently reported pattern is hard starting or stumbling when cold (below roughly 10°F) that impro","solution":"Pull codes — P0301-P0304 indicate the misfiring cylinder; P0351-P0354 indicate coil circuit faults. Confirm by swapping the suspect coil to an adjacent cylinder; if the misfire follows the coil, replace it (coils cannot be repaired). Inspect the plug well for oil and replace the spark plug tube seal if oil is present so the new coil isn't ruined. Replace the spark plugs at the same time. Forester ignition coil part numbers vary by year/engine (for example 22433AA691 on 2013-2018 2.5L and 22433AA590 on non-turbo 2009-2010); confirm the exact PN by VIN."},{"id":"subaru-forester-catalytic-converter-efficiency-failure-often-triggered-by-oi","make":"Subaru","model":"Forester","years":[2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021],"trims":["Base","Premium","Limited","Touring","Sport"],"engines":["FB25"],"title":"Catalytic Converter Efficiency Failure (P0420) — Often Triggered by Oil-Burning Contamination","description":"Foresters commonly throw a P0420 'Catalyst System Efficiency Below Threshold (Bank 1)' code and an illuminated check-engine light. While the converter itself is the part that degrades, the underlying root cause on FB25 Foresters is frequently the well-documented excessive-oil-consumption defect: burnt oil and unburned fuel coat and contaminate the catalyst, reducing its efficiency until it can no longer pass the down","solution":"Before condemning the converter, rule out cheaper causes: a lazy/failed rear O2 sensor and exhaust leaks can both mimic P0420. Verify the engine is not consuming oil at an excessive rate (a contaminated cat will quickly re-fail if oil consumption is unaddressed). Check VIN eligibility against Subaru service program WVI-19 (10yr/100k extended cat warranty) and the Yaeger oil-consumption settlement before paying out of pocket. If the catalyst is genuinely degraded, replace with a CARB-compliant OEM or direct-fit converter and a new rear O2 sensor."},{"id":"subaru-forester-valve-cover-gasket-spark-plug-tube-seal-oil-leak-causing-mis","make":"Subaru","model":"Forester","years":[2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024],"trims":["Base","Premium","Limited","Touring","Sport","Wilderness"],"engines":["FB25"],"title":"Valve Cover Gasket and Spark Plug Tube Seal Oil Leak Causing Misfires (FB25)","description":"The boxer engine's two valve covers face outward and sit low on each side, exposing the cork/rubber valve cover gaskets and the spark plug tube seals to heat cycling and the path of any leaking oil. As these seals harden and shrink, oil seeps out and visibly drips onto the exhaust (burning-oil smell from under the hood) and — more importantly — pools down inside the spark plug tubes. Oil in the plug tubes saturates t","solution":"Remove the affected valve cover and replace BOTH the valve cover gasket AND the spark plug tube seals at the same time (replacing only the cover gasket and leaving old tube seals lets oil keep reaching the plugs). Inspect and replace any oil-soaked spark plugs and ignition coils. The FB25 valve cover gasket is OEM 13294AA050 (supersedes/cross to 13294AA053); the gasket set that includes the spark plug tube/washer seal is 13293AA051. Clean oil residue off the block and re-torque the cover to spec."},{"id":"subaru-forester-ac-compressor-2014","make":"Subaru","model":"Forester","years":[2014,2015,2016,2017,2018,2019,2020],"trims":["2.5X","2.5X Limited","2.5X Premium","2.5i","2.5i Limited","2.5i Premium"],"engines":["FB25"],"title":"A/C Compressor Failure and Clutch Noise","description":"Foresters with the 2.5L FB25 engine experience premature A/C compressor failures, often with a noisy clutch or complete seizure. The compressor clutch bearing fails first, creating a grinding or squealing noise when the A/C is engaged. If not addressed, the compressor can seize and send metal debris through the entire A/C system, requiring replacement of the condenser, receiver/drier, and expansion valve in addition ","solution":"Replace A/C compressor assembly (Denso 471-6050 or Subaru OEM 73111SG010). If compressor seized and sent debris, flush the entire system and replace condenser, receiver/drier (Subaru 73520FJ001), and expansion valve. Use PAG 46 oil and charge with R-134a to factory spec (15.5 oz). A/C clutch relay and pressure switch should be tested before assuming compressor failure."},{"id":"subaru-forester-front-lower-control-arm-forward-bushing-premature-wear-steer","make":"Subaru","model":"Forester","years":[2014,2015,2016,2017,2018],"trims":["2.5i","2.5i Premium","2.5i Limited","2.5i Touring","2.0XT Premium","2.0XT Touring"],"engines":["2.5L FB25","2.0L FA20DIT Turbo"],"title":"Front Lower Control Arm Forward Bushing Premature Wear — Steering Wobble (TSB 05-63-18)","description":"The forward (front) bushing in the front lower control arms wears out prematurely on 4th-gen (SJ) Foresters, often by 40,000-70,000 miles on normally-driven, paved-road vehicles. As the bushing degrades it allows the control arm to shift, producing a rattle/clunk, a vibration or shudder felt through the steering wheel (especially on highway turns or undulations), uneven outer-edge tire wear, and a vague, unstable ste","solution":"Per TSB 05-63-18, replace the front lower control arm forward bushings (or the complete control arms) with the updated parts, then perform a four-wheel alignment. Independent shops typically replace both control arms as assemblies; budget roughly $400-700 per side in parts and labor, or about $900-1,400 for the pair plus alignment."},{"id":"subaru-forester-rear-suspension-clunk-2009","make":"Subaru","model":"Forester","years":[2009,2010,2011,2012,2013,2014,2015,2016,2017,2018],"trims":[],"engines":[],"title":"Rear Suspension Bushing Clunk Over Bumps","description":"Foresters from 2009-2018 develop a persistent clunking or knocking noise from the rear suspension when going over bumps, rough roads, or speed bumps. The cause is worn rear lateral link bushings and rear stabilizer bar end links. The rubber bushings dry out and crack, allowing metal-on-metal contact. The noise is often misdiagnosed as strut or shock failure.","solution":"Replace rear lateral link bushings (both inner and outer on each side). Replace rear stabilizer bar end links. Whiteline polyurethane bushings are a popular upgrade that lasts significantly longer than OEM rubber. If noise persists, check rear subframe mounting bushings. Torque all bolts to spec with the suspension loaded (wheels on ground or suspension compressed to ride height)."},{"id":"genesis-gv70-12v-auxiliary-battery-drain-dead-battery-bricking","make":"Genesis","model":"GV70","years":[2022,2023,2024,2025],"trims":["GV70 2.5T","GV70 3.5T","Electrified GV70"],"engines":["2.5T GDI I4","3.5T GDI V6","Dual-Motor Electric (Electrified GV70)"],"title":"12V Auxiliary Battery Drain and Dead-Battery 'Bricking'","description":"Owners across both the ICE and Electrified GV70 report the 12V battery going dead after the car sits for only a few days, leaving the vehicle unresponsive and unable to start ('bricked'). Genesis Roadside and dealers have told owners the car must be driven 30 minutes every 3-7 days to keep the 12V charged. Reported root causes vary: parasitic draw from electronic modules and telematics, the key fob staying in constan","solution":"Have the dealer perform a parasitic-draw test and load-test the 12V battery; replace the battery if a cell is bad (often done under warranty). Keep the key fob out of the car when parked for long periods, and on cars that sit, use a battery tender or drive ~30 minutes weekly. On Electrified GV70s, confirm the ICCU recalls (025G / 24V-204 family) are completed, since ICCU failure is a major cause of repeat 12V deaths. Persistent draw with no obvious cause warrants module-by-module isolation by the dealer."},{"id":"mitsubishi-outlander-12v-auxiliary-battery-parasitic-drain-repeated-dead-battery","make":"Mitsubishi","model":"Outlander","years":[2022,2023,2024],"trims":["ES","SE","SEL","LE","Platinum Edition","PHEV"],"engines":["2.5L PR25DD I4","2.4L PHEV (4B12) hybrid"],"title":"12V Auxiliary Battery Parasitic Drain / Repeated Dead Battery","description":"Fourth-generation Outlander and Outlander PHEV owners (2022+) report the 12V auxiliary battery repeatedly going flat, sometimes leaving the car dead in a day or two, even on nearly new vehicles and with the traction battery fully charged. Identified culprits on owner forums include the OEM infotainment/radio head unit failing to fully sleep, a driver's seat control module intermittently drawing current, a WiFi/telema","solution":"Diagnose parasitic draw with a multimeter (fuse-pull method) to isolate the offending circuit; check for infotainment/seat-module software updates at the dealer. Replace a degraded 12V battery (vented AGM type on PHEV) and verify DC-DC/alternator charging. Some owners fit a battery maintainer for vehicles parked for extended periods. Dealers have addressed specific VINs with module reprogramming."},{"id":"mitsubishi-outlander-ac-compressor","make":"Mitsubishi","model":"Outlander","years":[2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020],"trims":[],"engines":[],"title":"AC Compressor Failure","description":"The AC compressor in the Outlander is prone to premature failure, with the internal clutch bearing seizing or the compressor developing internal leaks. Failure typically occurs between 60,000 and 90,000 miles, leaving the vehicle without air conditioning.","solution":"Replace the AC compressor, receiver/drier, and expansion valve as a complete system. Flush the AC lines to remove debris from the failed compressor. Use the correct PAG oil specification for the replacement unit."},{"id":"mitsubishi-outlander-suspension-noise","make":"Mitsubishi","model":"Outlander","years":[2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024,2025,2026],"trims":[],"engines":[],"title":"Front Suspension Clunking and Noise","description":"The Outlander develops front suspension clunking and knocking noises over bumps and rough roads. Worn front stabilizer bar end links and strut mount bearings are the primary culprits, with noise appearing as early as 30,000 miles.","solution":"Replace the front stabilizer bar end links and strut mounts. Inspect the lower control arm bushings while the suspension is apart. OEM replacement parts are recommended as some aftermarket components have fitment issues."},{"id":"ram-1500-ecodiesel-fuel-pump-2014","make":"RAM","model":"1500","years":[2014,2015,2016,2017,2018,2019,2020,2021,2022],"trims":["Big Horn","Laramie","Laramie Longhorn","Limited","Limited Longhorn","Lone Star"],"engines":["3.0L EcoDiesel"],"title":"EcoDiesel Fuel Pump Failure / Stalling","description":"NHTSA 22V406 / FCA Z46 covers affected 2014-2019 RAM 1500 trucks with the 3.0L diesel, while 22V767 / FCA Z96 covers affected 2020-2022 RAM 1500 trucks with that engine. High-pressure fuel-pump failure can introduce debris or cause fuel starvation and an unexpected loss of drive power. Together the campaigns support the indexed model-year span, but only VIN-selected vehicles are included and no owner-frequency count ","solution":"Check the VIN for Z46 / 22V406 and Z96 / 22V767. Have the dealer replace the high-pressure fuel pump and inspect or replace additional fuel-system components as necessary, free of charge. If the engine stalls or loses power, use hazards, steer and brake to a safe location and arrange service. Do not buy a high-pressure pump, injector, rail or fuel-system kit from this page; campaign eligibility, contamination extent, completed remedy, current part number and VIN fitment must be established first."},{"id":"ram-1500-tipm-failure-2009","make":"RAM","model":"1500","years":[2009,2010,2011,2012,2013,2014,2015,2016],"trims":[],"engines":[],"title":"TIPM (Totally Integrated Power Module) Failure","description":"The TIPM controls most electrical functions and commonly fails, causing erratic behavior. The fuel pump relay inside the TIPM is particularly prone to failure, resulting in no-start conditions. Horn honking randomly, headlights flickering, and wipers activating on their own are common symptoms.","solution":"For fuel pump relay failure: Install an external bypass relay kit ($30-50 DIY) to power fuel pump directly. For complete TIPM replacement: Use remanufactured unit ($400-600) or new OEM ($800-1,200). Some electrical shops can rebuild existing TIPM for $200-400. Warranty lawsuit settlements may cover repairs for some VINs."},{"id":"ram-1500-rear-axle-pinion-seal-leak-differential-whine-accel-decel","make":"RAM","model":"1500","years":[2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023],"trims":[],"engines":["3.6L Pentastar V6","5.7L HEMI V8","3.0L EcoDiesel V6"],"title":"Rear Axle Pinion Seal Leak and Differential Whine on Accel/Decel","description":"Ram 1500 rear (and sometimes front) differential pinion seals weep gear oil at the pinion flange, leaving residue on the driveshaft yoke and a wet spot at the front of the diff. The leak itself is minor, but improper repair is the bigger problem: if the pinion nut is not torqued correctly (and a fresh crush spacer used), the pinion bearing preload is wrong and a whine develops weeks later — whine on acceleration poin","solution":"Replace the pinion seal using a new crush spacer (collapsible) and torque the pinion nut to spec to set proper bearing preload; using thread-locking adhesive on the nut helps prevent re-leaks. If a whine is already present, the pinion bearing and ring-and-pinion may need inspection/replacement and a re-shim. Verify gear-oil level and use the correct spec fluid (with friction modifier for limited-slip)."},{"id":"ram-1500-p0420-p0430-catalytic-converter-inefficiency-5-7l-hemi","make":"RAM","model":"1500","years":[2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021],"trims":[],"engines":["5.7L HEMI V8"],"title":"P0420/P0430 Catalytic Converter Inefficiency on 5.7L HEMI","description":"Ram 1500 5.7L HEMI trucks commonly throw P0420 (Catalyst System Efficiency Below Threshold, Bank 1) and P0430 (Bank 2). On these engines the most frequent true cause is not a worn catalyst but an exhaust leak — a cracked exhaust manifold or broken manifold bolts (the same source as the cold-start tick) — which lets the downstream O2 sensor read incorrectly, or a failing downstream O2 sensor itself. The actual catalyt","solution":"Before replacing the catalytic converter, inspect for exhaust manifold cracks/broken bolts and test the upstream and downstream O2 sensors; check for any PCM software update addressing catalyst-monitor sensitivity. Repair manifold leaks and replace a lazy downstream O2 sensor first. Only replace the catalytic converter once leaks and sensors are confirmed good. Address any underlying rich-running cause (MAF, fuel trim) so a new cat is not damaged."},{"id":"ram-1500-optional-air-suspension-compressor-failure-ride-height-error","make":"RAM","model":"1500","years":[2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023],"trims":["Laramie","Laramie Longhorn","Limited","Rebel"],"engines":[],"title":"Optional air suspension: compressor failure, ride-height errors, and cold-weather collapse","description":"RAM 1500s equipped with the optional 4-corner air suspension (common on Laramie, Longhorn, Limited, Rebel) suffer recurring failures. The most common is air-bag micro-leaks (usually a rear bag) that make the compressor run continuously to keep up; the overworked compressor draws in humid air, ingests moisture that freezes in the air lines/dryer in winter, and the system collapses with a 'Service Air Suspension' messa","solution":"Diagnose for air-bag leaks first (soapy-water test on bags/fittings) before condemning the compressor, since a leaking bag is the usual root cause of compressor burnout. Replace leaking air spring(s), then the compressor/dryer assembly if it has failed. Apply the latest ride-height software/TSB (08-152-24) for false 'stuck sensor' faults. Some owners convert to a conventional coil-spring kit to eliminate the system. Dealer compressor replacement is often ~$2,500-$3,300; DIY parts can be far less."},{"id":"ram-1500-etorque-mild-hybrid-2019","make":"RAM","model":"1500","years":[2019,2020,2021,2022,2023,2024,2025],"trims":[],"engines":[],"title":"eTorque Mild Hybrid System Failure","description":"The 2019+ RAM 1500 with eTorque mild hybrid system (standard on V6, optional on V8) experiences failures of the 48-volt battery pack, belt-driven motor generator (BDM), and eTorque control module. Symptoms include rough idle, stalling at stops, auto start-stop not working, and \"Service eTorque System\" warning messages. The 48V lithium-ion battery pack located under the rear seat deteriorates over time, especially in ","solution":"Diagnose with a Mopar wiTECH scan tool to identify if the 48V battery, BDM, or control module is at fault. Check TSB 08-074-20 REV.A for motor generator noise. If the 48V battery is degraded (below 42V resting), replace the battery pack under the rear seat ($800-1,500). If the BDM is failed, replace the unit and serpentine belt ($1,200-2,000). Software reflash may resolve intermittent issues. The eTorque system is covered under the powertrain warranty (5yr/60k miles)."},{"id":"ram-1500-p0011-intake-cam-timing-over-advanced-from-clogged-vvt-solen","make":"RAM","model":"1500","years":[2009,2011,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024],"trims":["Tradesman","Big Horn","Lone Star","Laramie","Rebel","Limited"],"engines":["5.7L HEMI V8 (VVT)","3.6L Pentastar V6"],"title":"P0011 — Intake Cam Timing Over-Advanced from Clogged VVT Solenoid / Cam Phaser (5.7 Hemi)","description":"On the RAM 1500, P0011 is overwhelmingly a Variable Valve Timing (VVT) fault on the 5.7L Hemi, and secondarily on the 3.6L Pentastar V6. The Hemi uses a single central cam phaser fed oil pressure through one oil control valve (the VVT solenoid, mounted at the front of the engine near the timing cover). The PCM commands the phaser to a target intake-cam angle and monitors the actual angle via the cam/crank sensors. Wh","solution":"Start with the cheap, high-yield steps: verify oil level and do a fresh oil-and-filter change using correct-viscosity oil (5W-20 on the Hemi), then clear the code and retest — dirty/degraded oil is the single most common trigger. If P0011 returns, replace the VVT/oil-control solenoid (clean the screen or renew), and perform the required cam/crank relearn afterward. If codes persist after a new solenoid, or the engine ticks and has high mileage, inspect the cam phaser, timing chain/guides and — critically on the Hemi — the camshaft lobes and lifters (MDS lifters), since VVT timing codes frequen"},{"id":"lincoln-aviator-rear-air-suspension","make":"Lincoln","model":"Aviator","years":[2020,2021,2022,2023,2024],"trims":["Reserve","Black Label","Grand Touring","Black Label Grand Touring"],"engines":["3.0L EcoBoost V6","3.0L Plug-in Hybrid"],"title":"Aviator Air Glide Suspension — Compressor and Bag Failures","description":"2020+ Aviator with the optional Air Glide suspension shares its compressor and air spring design with the related Ford Explorer ST/Platinum. Owners report compressor noise becoming progressively louder by 40,000-80,000 miles, then bag leaks (rear first), then compressor burnout. Warning message: \"Service Air Suspension.\"","solution":"Diagnose with FORScan to confirm air bag vs. compressor failure. OEM bags $700-$1,100 per corner installed. Compressor (Wabco/Continental unit) ~$600-$900 installed. Replace compressor dryer at the same time as a bag (~$80) — extends compressor life."},{"id":"lincoln-aviator-12v-battery-drain-repeated-dead-battery","make":"Lincoln","model":"Aviator","years":[2020,2021,2022],"trims":[],"engines":[],"title":"12-Volt Battery Drain from Third-Party App Modem Activity","description":"Ford SSM 50804 says some 2020-2022 Aviators with an activated modem may have 12-volt battery-drain symptoms when unaffiliated third-party phone applications repeatedly request vehicle commands such as lock, unlock, remote start, or location. Those calls can keep the vehicle network active. This is one documented cause, not proof that every dead battery is a TCU, latch, battery, or module failure. Ford separately expl","solution":"Identify and uninstall any non-Ford/Lincoln app that accesses the vehicle, then fully charge and test the 12-volt battery and monitor key-off draw and battery state of charge. If symptoms remain, follow normal Ford battery, battery-monitoring-sensor, charging-system, modem, and module network-sleep diagnostics. A Deep Sleep notification by itself is not a failed module; if state of charge does not change after charging or a BMS reset, continue the battery/BMS diagnostic path. Do not replace a latch, TCU, battery, or other module without a failed test, and do not present a maintainer as the rep"},{"id":"lincoln-aviator-total-loss-audio-from-rear-water-leak-damaging-audio-control","make":"Lincoln","model":"Aviator","years":[2020,2021,2022,2023],"trims":[],"engines":[],"title":"Lack of Audio with Rear-Liftgate or Spare-Tire Water Leak - TSB 23-2181","description":"Some 2020-2023 Aviators may exhibit lack of audio after rainfall or a car wash together with water in the rear-liftgate area or spare-tire area. Ford TSB 23-2181 directs Aviator-specific inspection of the power-liftgate grommet, margin seal and pushpins, electrical-wiring grommet, rear washer hose, body-hole plugs, BLIS-module seating, and BLIS harness grommets. The bulletin calls for ACM replacement when right-side ","solution":"Confirm both the audio symptom and rear water evidence, then follow the Aviator inspection sequence in TSB 23-2181. Correct only the leak path found: reseat or replace the specified grommet/strut when required, seat seals and connectors, repair plugs or washer-hose routing, and verify the BLIS module and harness grommets. If right-side water is present, follow the bulletin's ACM replacement step and use the VIN-specific parts catalog application. Dry and inspect affected connectors and trim as directed. Coverage depends on the vehicle's applicable warranty or service plan; this record has no c"},{"id":"nissan-frontier-timing-chain-qr25de-2005","make":"Nissan","model":"Frontier","years":[2005,2006,2007,2008,2009,2010,2011,2012],"trims":[],"engines":["QR25DE"],"title":"Timing Chain Rattle and Failure (QR25DE 4-Cylinder)","description":"The 4-cylinder QR25DE engine in the Frontier is prone to timing chain tensioner and guide failure, separate from the VQ40DE V6 issue. The primary timing chain tensioner loses pressure, allowing chain slack that causes a distinctive rattle on startup. If ignored, the chain can skip timing and cause valve damage. This issue typically manifests between 100,000-150,000 miles and is exacerbated by extended oil change inte","solution":"Replace the timing chain, tensioner, and guides. The QR25DE timing chain job is more straightforward than the VQ40DE since it is a 4-cylinder. Cost: $800-1,500 at an independent shop. Use OEM Nissan timing chain kit for best longevity. Maintain strict 5,000-mile oil change intervals after repair."},{"id":"nissan-frontier-timing-chain-2005","make":"Nissan","model":"Frontier","years":[2005,2006,2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019],"trims":["Desert Runner","PRO-4X","S","SC","SE","SL"],"engines":["VQ40DE"],"title":"Timing Chain Guide and Tensioner Failure (VQ40DE)","description":"The Nissan Frontier VQ40DE 4.0L V6 is notorious for timing chain guide and tensioner failure, typically occurring between 80,000-130,000 miles. The plastic chain guides deteriorate and break apart, causing chain rattle and potential engine damage. This is one of the most well-known issues with the Frontier. Nissan issued a Service Campaign for some model years.","solution":"Replace all timing chain guides, tensioners, and chains. The job requires significant labor as the engine must be partially disassembled. Use updated Nissan timing chain kit. Total cost: $1,500-3,000. Some independent shops specialize in this repair for $1,200-2,000."},{"id":"nissan-frontier-fuel-sending-unit-2005","make":"Nissan","model":"Frontier","years":[2005,2006,2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019],"trims":[],"engines":[],"title":"Fuel Sending Unit Failure and Inaccurate Gauge","description":"The Frontier fuel level sending unit is prone to failure, causing the fuel gauge to read inaccurately or erratically. The gauge may show full when the tank is half empty, drop suddenly from half to empty, or fluctuate randomly. This is caused by wear on the sending unit rheostat (variable resistor) inside the fuel tank. The issue can make it difficult to judge actual fuel level and risks running out of fuel unexpecte","solution":"Replace the fuel level sending unit inside the fuel tank. Access is through the rear seat or bed. The sending unit is part of the fuel pump assembly on some models. Cost: $200-500 for the part, $150-300 labor. Some owners replace just the sending unit float arm if available separately ($80-150)."},{"id":"nissan-frontier-rear-diff-bushing-2005","make":"Nissan","model":"Frontier","years":[2005,2006,2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021],"trims":[],"engines":[],"title":"Rear Differential Bushing Clunk","description":"The D40 Frontier develops a clunk from the rear end during acceleration and deceleration transitions, caused by worn rear differential mount bushings. The rubber bushings deteriorate over time, allowing the differential to shift and create a noticeable \"clunk\" when transitioning between acceleration and coast. This is one of the most commonly reported issues on Frontier forums and typically starts around 40,000-60,00","solution":"Replace the rear differential mount bushings with polyurethane or upgraded rubber bushings. DIY cost: $30-80 for bushings. Shop labor: $150-300. Some owners install solid differential mounts or polyurethane mounts for a more permanent fix, though these may increase NVH. The upper and lower diff mounts should both be replaced at the same time."},{"id":"gmc-terrain-1-5t-pcv-oil-leak-2018","make":"GMC","model":"Terrain","years":[2018,2019,2020,2021,2022,2023,2024,2025],"trims":[],"engines":["1.5L Turbo LFV","1.5L Turbo LYX"],"title":"1.5L Turbo PCV System Failure and Coolant/Oil Intrusion","description":"The 2018+ Terrain with the 1.5L turbocharged engine (LFV/LYX) experiences PCV (Positive Crankcase Ventilation) diaphragm failure inside the valve cover. The integrated PCV diaphragm tears, causing excessive crankcase pressure that forces oil into the intake manifold and intercooler. Symptoms include oily residue around the air intake and intercooler outlet pipe. In severe cases, excessive crankcase pressure also caus","solution":"Replace valve cover assembly with updated GM part (GM 12690058) which includes the revised PCV diaphragm. Clean intercooler and intake manifold of oil contamination. Check for coolant consumption alongside oil intrusion. Inspect air-to-water intercooler for coolant contamination — replacement if contaminated (GM 84446987)."},{"id":"cadillac-xt5-timing-chain-2017","make":"Cadillac","model":"XT5","years":[2017,2018,2019,2020,2021,2022,2023,2024,2025],"trims":[],"engines":["3.6L V6 LGX","3.6L V6 LFX","2.0T LSY"],"title":"3.6L V6 Timing Chain Issues (XT5 V6 models)","description":"The XT5 V6 models use the GM 3.6L V6 (LGX) which has improved timing chains over earlier versions but is not immune to timing chain stretch at higher mileage. The LGX is better than the earlier LFX but still uses three timing chains with plastic guides. Issues typically appear later (100,000-150,000 miles) compared to earlier 3.6L variants. The 2020+ XT5 2.0T models use a different engine (LSY) and are not affected b","solution":"Same timing chain replacement as SRX/CTS 3.6L. Cloyes 9-0753S kit, replace water pump simultaneously. The LGX timing chain typically lasts longer than the LFX, so preventive replacement at 100,000+ miles is recommended rather than the 80,000-mile interval for earlier engines."},{"id":"gmc-terrain-transmission-shudder-2010","make":"GMC","model":"Terrain","years":[2010,2011,2012,2013,2014,2015,2016,2017],"trims":[],"engines":["2.4L I4 LEA","3.0L V6 LF1"],"title":"6T40/6T45 6-Speed Transmission Shudder and Harsh Shifts","description":"The 2010-2017 Terrain uses the GM 6T40 (2.4L) and 6T45 (V6) 6-speed automatic transmissions, both of which suffer from torque converter shudder, harsh shifts, and solenoid failures. The shudder occurs at light throttle between 30-50 mph when the torque converter clutch locks up. Solenoid pack wear causes P0756, P0751, and P0776 transmission fault codes. The transmission is sensitive to fluid condition — the 6T40/6T45","solution":"Full fluid exchange with Dexron VI (ACDelco 10-9243 or equivalent). TCM calibration update. Solenoid pack replacement (GM 24272814) if codes present. Valve body replacement for internal failures. Fluid service every 40,000 miles recommended for stop-and-go use."},{"id":"cadillac-xt5-engine-thermostat-sticks-open-3-6l-lgx-triggers-p0128-steeri","make":"Cadillac","model":"XT5","years":[2017,2018,2019,2020],"trims":[],"engines":["LGX 3.6L V6"],"title":"Engine Thermostat Sticks Open on the 3.6L LGX - Triggers P0128, 'Steering Assist is Reduced' Message and A/C Shutdown","description":"The engine thermostat on the 3.6L LGX V6 commonly sticks in the open position, so the engine never reaches its target operating temperature. The ECM sets P0128 and, because the electric power steering assist and A/C compressor operation are both load-managed off engine/coolant state, the driver gets a 'Steering Assist is Reduced - Drive With Care' message and loses A/C, sometimes with noticeably heavier steering effo","solution":"Replace the thermostat/water outlet housing assembly (the thermostat is integral to the plastic housing on the LGX - it is not serviced separately) and refill/bleed the cooling system with DEX-COOL. Clear P0128, then verify coolant temperature reaches roughly 195-215F on a scan tool before condemning the steering rack or A/C compressor. Do not replace the power steering rack for this message until engine coolant temperature has been verified."},{"id":"cadillac-xt5-transmission-shudder-2017","make":"Cadillac","model":"XT5","years":[2017,2018,2019,2020,2021,2022,2023,2024,2025],"trims":[],"engines":[],"title":"8-Speed / 9-Speed Transmission Shudder and Harsh Shifting","description":"The Cadillac XT5 uses an 8-speed (2017-2019) or 9-speed (2020+) automatic transmission. The 8-speed shares the torque converter shudder issue with other GM 8-speed vehicles. The 9-speed (GM 9T50/9T65) can have harsh shifts, delayed engagement, and shift hunting. Both transmissions have been subject to multiple software calibration updates from GM. The 9-speed is particularly sensitive to fluid condition and requires ","solution":"First step is a TCM software update at the dealer - multiple calibrations have been released. For 8-speed shudder, a fluid exchange with Mobil 1 LV ATF HP may resolve it. The 9-speed typically responds well to software updates. Persistent issues may require torque converter replacement (8-speed) or valve body replacement (9-speed)."},{"id":"gmc-terrain-hvac-blend-door-actuator-failure","make":"GMC","model":"Terrain","years":[2010,2011,2012,2013,2014,2015,2016,2017],"trims":["SLE","SLT","Denali"],"engines":["2.4L Ecotec I4 (LAF/LEA)","3.0L V6 (LF1)","3.6L V6 (LFX)"],"title":"HVAC Blend Door Actuator Failure (Clicking Noise, No Temperature Control)","description":"The HVAC blend/mode-door actuators fail as their internal plastic gears strip, producing a repetitive clicking or knocking sound from behind the dash and causing loss of temperature or airflow control. On dual-zone systems one side commonly blows hot while the other blows cold, or the system sticks on one temperature. A click/pop typically means a stripped gear requiring replacement.","solution":"Replace the failed blend/mode-door actuator (OEM/ACDelco recommended to avoid repeat aftermarket failures) and recalibrate with a scan tool after installation. The temperature (blend) actuator is the most common failure; mode/recirc actuators can also fail."},{"id":"ford-f-150-3-5l-ecoboost-cam-phaser-rattle-cold-start","make":"Ford","model":"F-150","years":[2017,2018,2019,2020],"trims":["Raptor","Limited","Platinum","Lariat","King Ranch"],"engines":["3.5L EcoBoost V6 (twin-turbo GTDI)"],"title":"3.5L EcoBoost cam phaser rattle on cold start","description":"Second-gen 3.5L EcoBoost engines develop a loud rattle/knock from the front timing cover for 2-5 seconds on cold start (and sometimes at idle). The variable-cam-timing (VCT) phasers have a lock pin that fails to engage on startup, allowing the phaser to rattle against the cam sprocket. Over time the phasers and timing chain wear, which can throw cam/crank correlation codes and, if ignored, lead to further timing comp","solution":"Ford issued a PCM reflash (program 21B10) to change startup oil-pressure behavior and reduce phaser rattle, and Customer Satisfaction Program 21N03 to replace the cam phasers if the noise persists. Out of program, replacement of all four phasers plus timing chains/guides is a ~10-hour job. Replace phasers and timing chain set; use full-synthetic oil and stick to oil-change intervals to preserve VCT oil pressure."},{"id":"ford-f150-vacuum-pump-2015","make":"Ford","model":"F-150","years":[2015,2016,2017,2018,2019,2020],"trims":[],"engines":["2.7L EcoBoost","3.5L EcoBoost","EcoBoost"],"title":"Brake Vacuum Pump Failure (EcoBoost)","description":"The vacuum pump that provides brake assist on EcoBoost F-150s can fail, resulting in a hard brake pedal and reduced braking assist. Since turbo engines don't produce intake vacuum like naturally aspirated engines, they rely on this pump.","solution":"Replace vacuum pump. This is a safety-critical repair - do not drive with failed pump. Check for diagnostic codes related to brake booster. Inspect vacuum lines for leaks as well."},{"id":"ford-f-150-3-5l-ecoboost-primary-timing-chain-stretch-p0016-cold-start","make":"Ford","model":"F-150","years":[2011,2012,2013,2014,2015,2016,2017],"trims":[],"engines":["3.5L EcoBoost V6 (Gen 1)"],"title":"3.5L EcoBoost Primary Timing Chain Stretch — P0016 and Cold-Start Rattle","description":"Distinct from the cam-phaser cold-start rattle, the first-generation (2011-2016) 3.5L EcoBoost suffers genuine primary timing-chain wear ('stretch') because of its long chain routing and the high loads of a twin-turbo direct-injection V6. As the chain pins and rollers wear, the cam-to-crank relationship drifts and the PCM logs P0016 (and related correlation codes). The first symptom is usually a brief metallic rattle","solution":"Confirm with a scan tool (P0016 cam/crank correlation) and verify chain stretch versus a sticking VCT solenoid before tear-down. The fix is a full timing-chain overhaul — primary and secondary chains, guides, tensioners, phasers, and VCT solenoids. Use the updated Ford parts; many shops replace the cam-position sensors and water pump while in there. Stay on the 5W-30 spec, change oil every 5,000 miles, and avoid extended intervals. Major job: $1,800-$3,000+ with labor. Catching it at the first cold-start rattle prevents engine destruction."},{"id":"ford-f-150-4-6l-5-4l-2-valve-triton-timing-chain-tensioner-plastic-guid","make":"Ford","model":"F-150","years":[1997,1998,1999,2000,2001,2002,2003,2004],"trims":["XL","XLT","Lariat","FX4","King Ranch"],"engines":["4.6L Triton 2V V8","5.4L Triton 2V V8"],"title":"4.6L / 5.4L 2-Valve Triton Timing Chain Tensioner and Plastic Guide Rattle","description":"The 2-valve 4.6L and 5.4L Triton V8s (distinct from the later 3-valve cam-phaser motors) use hydraulic timing-chain tensioners and plastic chain guides that wear and fail with age. The tensioners bleed down oil pressure overnight, so the chains slap on cold start; over time the brittle plastic guides crack and break, letting the chains rattle continuously and eventually skip timing or damage cam gears. Neglected oil ","solution":"Address a persistent cold-start rattle promptly. Replace both timing chain tensioners and the plastic guides (and chains if stretched) with an updated timing kit; inspect the cam/crank sprockets. Maintain oil changes with the correct grade and use an anti-drainback-quality filter to preserve start-up oil pressure."},{"id":"ford-f-150-4r70w-4r75w-automatic-transmission-failure-no-reverse-loss-f","make":"Ford","model":"F-150","years":[1997,1998,1999,2000,2001,2002,2003,2004,2005,2006,2007,2008],"trims":["XL","XLT","Lariat","FX4","King Ranch"],"engines":["4.2L Essex V6","4.6L Triton V8","5.4L Triton V8"],"title":"4R70W / 4R75W Automatic Transmission Failure — No Reverse, Loss of Forward Gears, and Slipping","description":"The 4R70W (and later 4R75W/4R75E) 4-speed automatic behind the 4.2L V6 and 4.6L/5.4L V8s is prone to several high-mileage failures: a broken reverse (cast) band that produces a loud POP and loss of reverse; a cracked forward-clutch drum snap-ring groove on 2005+ units causing loss of ALL forward gears while reverse still works; worn overdrive band and clutches causing slipping; and solenoid-body/servo wear causing ha","solution":"Diagnose fluid condition (burnt smell, metal), line pressure, and DTCs before teardown. Repair typically means a full rebuild with upgraded forward drum/snap ring, new bands, updated solenoid pack, and torque converter; add an auxiliary transmission cooler if the truck tows. Regular fluid/filter service (Mercon V) is the main preventive measure."},{"id":"ford-f-150-internal-radiator-transmission-cooler-fails-coolant-atf-cros","make":"Ford","model":"F-150","years":[1997,1998,1999,2000,2001,2002,2003,2004,2005,2006,2007,2008,2009,2010],"trims":["XL","XLT","Lariat","FX4","King Ranch"],"engines":["4.2L Essex V6","4.6L Triton V8","5.4L Triton V8"],"title":"Internal Radiator Transmission Cooler Fails — Coolant/ATF Cross-Contamination ('Strawberry Milkshake')","description":"F-150s with an automatic transmission route ATF through a cooler built into the radiator end tank. When the internal barrier cracks or corrodes, the two fluids cross-contaminate: pink/foamy 'strawberry milkshake' ATF appears in the coolant and coolant gets into the transmission. Coolant is highly destructive to transmission clutches and can cause total transmission failure if driven on. The radiator can fail internal","solution":"Replace the radiator immediately and stop driving once cross-contamination is confirmed. Flush the cooling system thoroughly and do multiple transmission fluid/filter services (or a full flush) to purge coolant from the trans; inspect for internal transmission damage. Bypassing the radiator cooler with an external cooler prevents recurrence."},{"id":"ford-f-150-tank-fuel-pump-failure-whining-hard-starting-stalling-under","make":"Ford","model":"F-150","years":[1997,1998,1999,2000,2001,2002,2003,2004],"trims":["XL","XLT","Lariat","FX4","King Ranch"],"engines":["4.2L Essex V6","4.6L Triton V8","5.4L Triton V8"],"title":"In-Tank Fuel Pump Failure — Whining, Hard Starting, Stalling Under Load, and No-Start","description":"The in-tank electric fuel pump on 1997-2004 F-150s wears out at high mileage (commonly 150k+), producing a loud whine from the tank, hard starting, and stalling that gets worse when the engine is warm or under load (climbing hills, towing). It often fails intermittently first, then leaves the truck as a crank-no-start. The dash fuel gauge can also read erratically as the sending unit in the same module fails. Note: a","solution":"Verify fuel pressure (~35-45 psi) and check the inertia switch and pump fuse/relay before replacing. Replace the in-tank pump/sender module and, in salt-belt trucks, inspect the fuel-tank straps at the same time. Keep the tank above 1/4 to help cool and lubricate the pump."},{"id":"ford-f-150-iwe-failure-front-end-grinding-partial-4x4-hub-engagement","make":"Ford","model":"F-150","years":[2004,2005,2006,2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024],"trims":[],"engines":["All 4x4 (3.5L EcoBoost","5.0L V8","2.7L EcoBoost","5.4L V8","3.5L V6)"],"title":"IWE (Integrated Wheel End) Failure — Front-End Grinding and Partial 4x4 Hub Engagement","description":"Ford's 4x4 F-150s use a vacuum-operated Integrated Wheel End (IWE) system instead of conventional locking hubs: vacuum keeps the front hubs UNLOCKED in 2WD and is released to lock them for 4WD. The system relies on vacuum lines, a hood-area solenoid, and a check valve that are highly vulnerable to water, road salt, and cracking. A single leak causes the hubs to partially engage, producing a loud grinding or clicking ","solution":"Diagnose in steps: replace the cheap IWE check valve first, inspect/replace cracked vacuum lines and the IWE solenoid (often water-drenched below the cowl), then replace the IWE hub-lock actuators themselves if grinding persists. Confirm it is the IWE and not a failed wheel hub/bearing (IWE noise goes away in 4WD; a bad bearing does not). OEM IWE actuator part numbers: 7L1Z-3C247-A (2004-2014) and HL1Z-3C247-A (2015+); check valve and solenoid sold separately. Check valve ~$15-$40; actuators ~$80-$180 each; full system repair commonly $200-$700 with labor."},{"id":"ford-f150-oil-pan-leak-2015","make":"Ford","model":"F-150","years":[2015,2016,2017,2018,2019,2020],"trims":[],"engines":["3.5L EcoBoost","2.7L EcoBoost","EcoBoost 3.5"],"title":"EcoBoost Oil Pan Leak","description":"The EcoBoost engines can develop oil leaks from the oil pan gasket. The leak often appears at the rear of the oil pan and can drip onto exhaust components, causing a burning oil smell. This is common on trucks with higher mileage.","solution":"Replace oil pan gasket. The repair is labor-intensive as the subframe often needs to be lowered for access. Use OEM gasket for best results. Clean oil pan and block mating surfaces thoroughly."},{"id":"ford-f-150-3-5l-ecoboost-fuel-injector-failure-startup-misfire-rough-id","make":"Ford","model":"F-150","years":[2011,2012,2013,2014,2015,2016,2017,2018,2019,2020],"trims":[],"engines":["3.5L EcoBoost V6"],"title":"3.5L EcoBoost Fuel Injector Failure — Startup Misfire, Rough Idle, and Fuel-Injector DTCs","description":"The 3.5L EcoBoost's high-pressure direct (GDI) injectors run at diesel-like pressures and are a common failure item, especially at higher mileage and after heat-soak. A stuck-open or electrically failing injector floods a cylinder and can wash down neighboring cylinders on the same bank, producing a cold-start misfire that often smooths out once warm. It commonly sets injector-circuit codes (P0201-P0206) alongside mi","solution":"Read freeze-frame and identify the specific cylinder; compare fuel-injector balance/contribution data. Swap or replace the failed GDI injector (intake manifold removal required for access) and inspect for fuel-washed plugs. Replace plugs/coils on the affected cylinder if fouled. Verify high-pressure fuel pump output and low-side pressure to rule out supply issues before replacing multiple injectors."},{"id":"ford-f-150-6r80-6-speed-automatic-harsh-1-2-upshift-erratic-shifting-le","make":"Ford","model":"F-150","years":[2009,2010,2011,2012,2013,2014,2015,2016,2017],"trims":[],"engines":["3.5L EcoBoost V6","5.0L Coyote V8","3.7L Ti-VCT V6","6.2L V8"],"title":"6R80 6-Speed Automatic Harsh 1-2 Upshift / Erratic Shifting and Lead-Frame Solenoid Body Failure","description":"The 6R80 six-speed automatic (2009-2017 F-150) is generally durable but is widely reported for a harsh, banging 1-2 upshift and erratic/flaring shifts, with thousands of NHTSA complaints. The internal solenoid body 'lead frame' (the mechatronic wiring carrier) can crack or develop failing solenoid calibration, and the adapt strategy struggles to relearn after service. The classic symptom is a 1-2 shift so abrupt owne","solution":"Start with a full fluid-and-filter service using Mercon LV (the 'lifetime fill' should still be serviced ~every 60k, sooner with towing). Have the dealer flash the PCM/TCM to the latest calibration — Ford released shift-quality calibration updates that fix many harsh/delayed-engagement complaints as the first repair. Persistent harsh shifting or specific solenoid codes call for a solenoid body / lead-frame replacement (Ford solenoid body assembly, commonly cross-referenced as Sonnax/aftermarket units). A TCM adaptive (keep-alive) reset and relearn is required after repairs. Fluid service $200-"},{"id":"ford-f-150-coolant-degas-overflow-bottle-cracks-quick-connect-fitting-l","make":"Ford","model":"F-150","years":[2015,2016,2017,2018,2019,2020,2021,2022,2023],"trims":[],"engines":["2.7L EcoBoost V6","3.5L EcoBoost V6","5.0L Ti-VCT V8"],"title":"Coolant Degas / Overflow Bottle Cracks and Quick-Connect Fitting Leaks","description":"The plastic pressurized coolant degas (overflow/expansion) bottle and the plastic quick-connect tees/Y-fittings that route coolant between the block, radiator, and bottle develop hairline cracks and seep, especially at seams and hose necks and in cold weather where the square-cut O-rings on the quick-connects shrink. Owners chase a slow coolant loss and sweet smell that is hard to pinpoint because the crack only weep","solution":"Pressure-test the cooling system to reveal the weep. Replace the degas bottle and any cracked plastic tee/Y quick-connect fittings as an assembly — a new hose/fitting will not seal reliably on an old bottle neck. Replace shrunken O-rings on quick-connects. Refill with the correct Ford orange/yellow spec coolant and burp the system."},{"id":"ford-f-150-dpfe-egr-pressure-sensor-failure-rough-idle-stalling-p0401","make":"Ford","model":"F-150","years":[1997,1998,1999,2000,2001,2002,2003,2004],"trims":["XL","XLT","Lariat","FX4","King Ranch"],"engines":["4.2L Essex V6","4.6L Triton 2V V8","5.4L Triton 2V V8"],"title":"DPFE / EGR Pressure Sensor Failure — Rough Idle, Stalling, and P0401 (2-Valve Triton)","description":"The Delta Pressure Feedback EGR (DPFE) sensor and the EGR throttle-body spacer passages are a chronic Check-Engine source on 1997-2004 4.2L/4.6L/5.4L trucks. The ceramic DPFE sensor drifts or cracks, and the narrow 90-degree EGR elbow passages carbon up until flow is blocked, setting P0401 (insufficient EGR flow). The result is a rough idle, stumble or stall when coming to a stop, hesitation, and reduced fuel economy","solution":"Test the DPFE sensor voltage and manually apply vacuum to the EGR valve at idle to confirm the valve/passages are clear. Replace the DPFE sensor (inexpensive, ~15-minute job) and clean the carbon-clogged EGR tube/throttle-body spacer passages. Replace cracked vacuum lines and the EGR valve only if proven faulty."},{"id":"ford-f-150-p0171-p0174-lean-codes-from-cracked-pcv-elbow-intake-vacuum","make":"Ford","model":"F-150","years":[2004,2005,2006,2007,2008],"trims":[],"engines":["4.6L V8","5.4L Triton 3V V8"],"title":"P0171/P0174 Lean Codes from Cracked PCV Elbow / Intake Vacuum Leak (Triton)","description":"The 11th-gen Triton V8s are known for setting both bank lean codes (P0171 and P0174) simultaneously due to a vacuum leak — most notoriously the brittle rubber PCV hose elbow hidden at the back of the intake manifold, which cracks from heat. A dirty MAF sensor or leaking intake gaskets can produce the same codes. Because both banks go lean together, the cause is almost always a shared air leak rather than a single inj","solution":"Check idle fuel trims (high positive at idle that normalize at 2500 rpm points to a vacuum leak), then smoke-test the intake. Replace the cracked PCV elbow/hose at the rear of the manifold (the most common fix) and inspect intake gaskets. Clean the MAF sensor with MAF-safe cleaner. Reset trims and reverify after repair."},{"id":"ford-f-150-sync-2-sync-3-apim-failure-black-screen-freezing-reboot-loop","make":"Ford","model":"F-150","years":[2013,2014,2015,2016,2017,2018,2019,2020],"trims":[],"engines":["All (infotainment, engine-independent)"],"title":"SYNC 2 / SYNC 3 APIM Failure — Black Screen, Freezing, and Reboot Loops","description":"The Accessory Protocol Interface Module (APIM) — the computer behind the SYNC 2 and SYNC 3 touchscreen — is a very common failure on 2013-2020 F-150s. Its internal electronics and onboard flash storage degrade over time, producing a black/unresponsive screen (sometimes with backlight on), constant reboot loops stuck at the Ford logo, frozen touch input, and loss of backup-camera display, navigation, phone, and HVAC c","solution":"First try a master reset and, importantly, update the APIM to the latest software level — Ford found many returned APIMs were simply running outdated software and did not actually need replacement (TSB guidance for SYNC 3 performance concerns). If the module is truly failed, replace the APIM; a replacement MUST be programmed (As-Built) to the vehicle's VIN/options via Ford service software or FORScan with an extended license — it is not plug-and-play. 2016 trucks adding CarPlay also need USB hub HC3Z-19A387-F. Software update may be free/low cost; programmed APIM replacement typically $400-$90"},{"id":"ford-f-150-water-leak-rear-window-third-brake-light-wet-headliner-carpe","make":"Ford","model":"F-150","years":[1997,2004,2005,2006,2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020],"trims":[],"engines":["All engines"],"title":"Water Leak at Rear Window / Third Brake Light — Wet Headliner, Carpet, and Cab-Corner Rust","description":"F-150s have a long-running problem with rainwater entering the cab from the top rear of the cab. Two sources dominate: the foam/rubber gasket behind the high-mounted third brake light dries out and cracks, and the butyl-tape seal around the fixed rear window (or the slider track) deforms with age. Water runs down inside the cab, soaking the headliner and rear carpet and pooling behind the rear seat. Because the cab c","solution":"Pinpoint the source with a careful water test from the bottom up. If the third brake light is the source, remove it and replace the foam gasket and reseal (a common, inexpensive fix). If the rear window is leaking, the back glass must be reset with fresh butyl tape/urethane, or a cracked slider seal replaced. Dry the headliner and carpet thoroughly and treat any cab-corner rust before it perforates; verify cab drain paths are clear. Typical parts+labor for the gasket/reseal runs roughly $100-$300; bodywork for resulting rust is far more."},{"id":"ford-f150-carrier-bearing-2015","make":"Ford","model":"F-150","years":[2015,2016,2017,2018,2019,2020],"trims":[],"engines":[],"title":"Driveshaft Carrier Bearing Failure","description":"The two-piece driveshaft uses a center support (carrier) bearing that can wear out, causing vibration and noise. The rubber support degrades over time, especially in hot climates or with heavy towing. Ford TSB addresses this issue.","solution":"Replace the carrier bearing assembly ($150-300 parts). Consider upgrading to a heavy-duty carrier bearing if towing frequently. The job requires dropping the driveshaft and is about 2-3 hours labor. Some owners upgrade to aftermarket carrier bearings with greaseable Zerk fittings for longer life."},{"id":"ford-f-150-sync-4-12-inch-touchscreen-goes-black-freezes-reboots-startu","make":"Ford","model":"F-150","years":[2021,2022,2023,2024],"trims":[],"engines":["All engines (trucks equipped with the 12-inch SYNC 4 screen)"],"title":"SYNC 4 12-inch Touchscreen Goes Black, Freezes, or Reboots on Startup","description":"14th-gen F-150s with the 12-inch SYNC 4 infotainment display commonly suffer a black/blank or frozen screen at startup — sometimes with no Ford logo, sometimes stuck on the splash screen, and sometimes unresponsive for several minutes. Owners report it occurring intermittently (some 2023 trucks roughly 10% of startups) and note it worsened after certain over-the-air updates (e.g., the 4.2.2 and 6.8 OTA builds). With ","solution":"Perform a hard reset by pressing and holding the power and right-seek buttons for about 10 seconds until the screen reboots. Keep SYNC software current but be aware some OTA builds introduced the regression — check Ford's update notes and, if a recent update triggered it, ask the dealer about the latest stable build or a master reset. If resets stop working or the screen stays dead, the dealer can reflash or, in persistent cases, replace the APIM/display module. Allow extra time after large updates, during which the screen can be unresponsive for 2-15 minutes by design."},{"id":"ford-f-150-c-evaporator-core-leak-weak-warm-c-musty-smell","make":"Ford","model":"F-150","years":[2012,2013,2014,2015,2016,2017,2018,2019,2020],"trims":[],"engines":["3.5L EcoBoost V6","2.7L EcoBoost V6","5.0L Ti-VCT V8","5.4L Triton V8"],"title":"A/C Evaporator Core Leak — Weak/Warm A/C and Musty Smell","description":"The evaporator core inside the dash develops small refrigerant leaks that slowly bleed the system down, leaving the A/C blowing warm or only cold intermittently; a musty odor is a common companion complaint. Because the evaporator is buried behind the dash, the leak is easy to miss and repeat 'recharge' visits don't hold. CarComplaints documents evaporator-leak complaints across several model years, and it is one of ","solution":"Confirm the leak with dye or an electronic sniffer / nitrogen pressure test after verifying it isn't a condenser, line, or O-ring leak (cheaper to fix). Evaporator replacement requires dash/HVAC-box removal, evacuation, new O-rings and desiccant/accumulator, and a proper recharge to spec. Replace the cabin filter and treat the case to address the musty smell."},{"id":"ford-f-150-door-ajar-switch-sticks-dome-lights-stay-battery-drain","make":"Ford","model":"F-150","years":[1997,1998,1999,2000,2001,2002,2003,2004,2005,2006,2007,2008,2009,2010,2011,2012,2013,2014],"trims":[],"engines":["4.2L V6","4.6L V8","5.4L Triton V8","3.5L EcoBoost V6","5.0L Ti-VCT V8"],"title":"Door Ajar Switch Sticks — Dome Lights Stay On and Battery Drain","description":"The door-ajar switch built into the door latch sticks or corrodes so the truck thinks a door is open. The result is a 'door ajar' warning that stays on, interior/dome lights that won't shut off, chimes, and a parasitic battery drain that can leave the truck dead overnight. It is one of the most common and widely searched F-150 electrical annoyances across many model years, and is usually a very cheap fix.","solution":"Isolate which door by watching the message center as you cycle each latch. Spray the latch/switch with a penetrant or electrical/brake cleaner and cycle the door 10-20 times to free the contacts — this fixes most cases. If it recurs, replace the door-ajar/jamb switch or the door latch assembly. Verify the interior lights and drain are gone with a parasitic draw test."},{"id":"ford-f-150-driver-s-door-master-power-window-switch-failure","make":"Ford","model":"F-150","years":[2009,2010,2011,2012,2013,2014],"trims":[],"engines":["All (electrical, engine-independent)"],"title":"Driver's Door Master Power Window Switch Failure","description":"The driver's door master switch on 2009-2014 F-150s commonly fails electrically (distinct from the mechanical window-regulator/cable failure). Carbon builds up on the internal contacts from current arcing, and the switch's exposed door-panel location lets moisture in when the window is lowered in rain — both degrade the contacts. Because the master switch and the front passenger switch share wiring splices, a failing","solution":"Test for power and ground at the switch and inspect the connector for corrosion/moisture before condemning it. The usual fix is to replace the driver's master window switch assembly (cleaning carbon-fouled contacts is a temporary fix at best). Check the relevant fuse first. OEM part numbers: 9L3Z-14529-AD / 9L3Z-14529-AE (2009-2010) and BL3T-14540-AAW for 2011-2014. Aftermarket switches are inexpensive. Switch $25-$90; about a 30-60 minute DIY, or ~$100-$200 at a shop."},{"id":"ford-f-150-evap-canister-purge-valve-stuck-open-hard-start-after-refuel","make":"Ford","model":"F-150","years":[2011,2012,2013,2014,2015,2016,2017,2018,2019,2020],"trims":[],"engines":["3.5L EcoBoost V6","2.7L EcoBoost V6","5.0L Coyote V8","3.3L Ti-VCT V6"],"title":"EVAP Canister Purge Valve Stuck Open — Hard Start After Refueling, Rough Idle, P0455/P0496","description":"The EVAP canister purge valve (purge solenoid) on F-150s commonly sticks in the open position, allowing raw fuel vapor from the charcoal canister to be pulled into the intake when it shouldn't be. This floods the cylinders with vapor — owners report a vehicle that cranks but won't start (or stumbles badly) immediately after filling the tank, then runs fine once it clears. A stuck-open or leaking purge valve, along wi","solution":"Verify with a smoke test before replacing parts — roughly 30% of P0455/P0456 codes are a loose or cracked gas cap, so reseat/replace the cap and clear first. If the purge valve fails to hold vacuum when commanded closed (it should seal), it is leaking and must be replaced. Inspect the rubber lines from the canister to the valve and to the intake for cracks/collapse and reseat loose connections per TSB 19-2132. After repair, clear codes and complete a drive cycle to allow the EVAP monitor to re-run. The purge valve sits near the throttle body/intake and is a quick R&R; expect roughly $25-$70 fo"},{"id":"ford-f-150-power-tailgate-lock-actuator-failure-tailgate-opens-by-itsel","make":"Ford","model":"F-150","years":[2015,2016,2017,2018,2019,2020,2021,2022,2023],"trims":[],"engines":["All (body, engine-independent)"],"title":"Power Tailgate Lock Actuator Failure / Tailgate Opens by Itself","description":"On 2015+ aluminum-body F-150s with the power-locking/keyless tailgate, the electric tailgate lock actuator weakens and fails — it clicks but won't lock/unlock, operates intermittently (especially in cold weather), grinds, or quits entirely so the tailgate won't open from the key fob or handle. A second, well-documented failure mode is the tailgate releasing or unlocking on its own: a connector near the spare tire let","solution":"For no-open/intermittent operation, replace the tailgate lock actuator motor — OEM GC3Z-9943170-E (also cross-referenced FL3Z-9943170-C / GC3Z-9943170-A/B) for 2015-2023 power-tailgate trucks; the manual handle remains as a backup. For self-opening/unlocking, clean and dielectric-grease the corroded connector near the spare tire (inspect every ~6 months in salt regions) and repair any chafed wiring; verify BCM isn't seeing a false signal. Actuator ~$60-$180; DIY replacement ~30-45 min, or $150-$250 at a dealer."},{"id":"ford-f150-blend-door-2015","make":"Ford","model":"F-150","years":[2015,2016,2017,2018,2019,2020,2021,2022,2023],"trims":[],"engines":[],"title":"HVAC Blend Door Actuator Failure","description":"The HVAC blend door actuators can fail, causing clicking noises from the dashboard and inability to control air temperature. Air may blow only hot or only cold regardless of settings. Multiple actuators are used and any can fail.","solution":"Replace failed blend door actuator. Actuators are located behind dashboard and require some disassembly. Consider replacing multiple actuators if one fails as others may follow. OEM parts recommended."},{"id":"jeep-grand-cherokee-front-wheel-speed-sensor-failure-triggering-abs-esp-bas-trac","make":"Jeep","model":"Grand Cherokee","years":[2019],"trims":[],"engines":[],"title":"2019 Grand Cherokee ABS Warning - Diagnose the Wheel-Speed Circuit First","description":"On 2019 model-year Jeep Grand Cherokee (WK) vehicles, an ABS warning that diagnosis traces to a wheel-speed circuit may be caused by an incompletely latched connector, water intrusion and corroded connector pins, rust or contamination at the sensor and tone wheel, or a faulty sensor. FCA warns that replacing a good sensor while leaving a damaged harness in place can cause the concern to return. The previous card inco","solution":"Read the ABS module and compare individual wheel-speed live data to isolate the affected circuit. Inspect the connector latch, pins, and harness for water intrusion, corrosion, routing problems, or damage; replace a damaged harness rather than the sensor. Inspect and clean the sensor mounting area and tone wheel, reinstall the sensor, and retest the signal. Replace the sensor only when electrical and signal testing confirms it is faulty, then clear faults and verify normal wheel-speed data on a road test. Confirm any replacement by VIN and installed equipment before ordering."},{"id":"jeep-grand-cherokee-air-suspension-2011","make":"Jeep","model":"Grand Cherokee","years":[2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021],"trims":[],"engines":[],"title":"2011-2021 Quadra-Lift Warning or Uneven Ride Height - Diagnose Before Parts","description":"Quadra-Lift is a closed, electronically controlled air-suspension system, so a Service Air Suspension message, a low corner, or a denied height change does not identify one universal failed part. The factory diagnostic path covers electrical and communication faults, fuses and voltage, pinched or damaged lines, leaking springs, disconnected sensor linkages, water or blockage in the compressor intake, air-mass loss, v","solution":"Confirm the vehicle is equipped with Quadra-Lift sales code SER, record the exact ASCM DTCs and environmental data, and check VIN/build-date-specific FCA bulletins before ordering hardware. Follow the factory sequence: repair voltage or communication faults first; inspect fuses, air lines, springs, height-sensor linkages, compressor intake/filter, and visible plumbing; then use a capable scan tool to run the Air Mass and Air Ride Height routines and follow the DTC-specific tree. On 2011-2012 vehicles built before May 1, 2012, U0415-00 or C159E-15 with a Service Air Suspension message may be ad"},{"id":"jeep-grand-cherokee-body-control-module-electrical-faults-causing-uconnect-reboo","make":"Jeep","model":"Grand Cherokee","years":[2014,2015,2016,2017,2018],"trims":[],"engines":[],"title":"2014-2018 Uconnect Reboots, Accessory Faults or Battery Drain - Separate the Causes","description":"Uconnect resets or a blank screen, intermittent accessories, a discharged battery, and communication faults may occur together, but they do not establish that the Body Control Module is defective. Radio software or hardware, a weak battery or charging problem, poor power or ground, damaged CAN wiring or terminals, another module that will not sleep, and a true internal module fault can overlap. FCA has a software bul","solution":"Start with a complete vehicle scan and save active, stored, and environmental data before clearing anything. Load-test the battery, verify charging voltage, and repair low-voltage faults first. Inspect the relevant fuses, power feeds, grounds, connectors, and CAN wiring, then measure key-off draw only after the vehicle has completed its normal sleep period and isolate the circuit that remains awake. For radio resets, identify the exact radio sales code and vehicle build date and check the VIN for the applicable FCA software or radio procedure. For a lost-communication fault, determine whether "}]

const BUYLINK = {
  type: 'object', additionalProperties: false,
  properties: {
    vendor: { type: 'string' },
    url: { type: 'string' },
    linkType: { type: 'string', enum: ['product', 'catalog'] },
  },
  required: ['vendor', 'url', 'linkType'],
}

const PART = {
  type: 'object', additionalProperties: false,
  properties: {
    component: { type: 'string' },
    oemPartNumber: { type: 'string' },
    aftermarketXref: { type: 'array', items: { type: 'string' } },
    priceLow: { type: 'number' },
    priceHigh: { type: 'number' },
    buyLinks: { type: 'array', items: BUYLINK },
    note: { type: 'string' },
    fitmentBasis: { type: 'string' },
  },
  required: ['component', 'buyLinks', 'note', 'fitmentBasis'],
}

const RESOLVE_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    resolved: { type: 'boolean' },
    unresolvedReason: { type: 'string' },
    parts: { type: 'array', items: PART },
  },
  required: ['resolved', 'parts'],
}

const VERDICT_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    fitmentConfirmed: { type: 'boolean' },
    partNumberPlausible: { type: 'boolean' },
    linksAreRealProductPages: { type: 'boolean' },
    isCorrectComponentForFix: { type: 'boolean' },
    confidence: { type: 'number' },
    reason: { type: 'string' },
  },
  required: ['fitmentConfirmed', 'partNumberPlausible', 'linksAreRealProductPages', 'isCorrectComponentForFix', 'confidence', 'reason'],
}

function resolvePrompt(t) {
  return [
    `You resolve a car problem's documented fix into the SPECIFIC PART an owner needs to buy.`,
    ``,
    `VEHICLE: ${t.make} ${t.model}`,
    `Model years affected: ${(t.years || []).join(', ') || '(unspecified)'}`,
    `Engines: ${(t.engines || []).join(', ') || '(unspecified)'}`,
    `Trims: ${(t.trims || []).join(', ') || '(unspecified)'}`,
    ``,
    `THE ISSUE: ${t.title}`,
    `Description: ${t.description}`,
    `THE DOCUMENTED FIX: ${t.solution}`,
    ``,
    `Find the part(s) that fix actually requires. For each part give: component (plain name an owner`,
    `would recognise), oemPartNumber if you can confirm it, aftermarketXref (equivalent parts by`,
    `brand and number), priceLow/priceHigh in USD, note, fitmentBasis, and buyLinks.`,
    ``,
    `FITMENT IS THE HARD REQUIREMENT:`,
    `  * The part number must fit THIS model, THESE years, and THIS engine. Part numbers differ`,
    `    across engines in the same model and across years in the same generation. A number that is`,
    `    right for one engine and wrong for another is the single most damaging error you can make —`,
    `    it sends someone to buy a part that will not fit their car.`,
    `  * State in fitmentBasis exactly how you confirmed fitment (e.g. "RockAuto catalog for 2015`,
    `    Forester 2.5i", "Subaru parts catalog year/engine lookup"). If you cannot state a real`,
    `    basis, you have not confirmed it.`,
    `  * If the correct part varies by year or engine within this issue, return the variants as`,
    `    separate entries with the distinction stated in note — do NOT pick one and hope.`,
    ``,
    `BUY LINKS — the rules that matter most:`,
    `  * ONLY link product pages you actually found in search results and confirmed carry this part.`,
    `    NEVER construct a URL from a pattern. A fabricated link that 404s is worse than no link.`,
    `  * linkType "product" = a specific product page. "catalog" = a legitimate parts-catalog result`,
    `    page for this exact part number. Prefer product.`,
    `  * Good vendors for this catalogue: RockAuto, Amazon, eBay, PartsGeek, and manufacturer parts`,
    `    sites (e.g. subarupartsdeal, acurapartswarehouse).`,
    `  * For Amazon links, append the affiliate tag: add "?tag=au7o-20" (or "&tag=au7o-20" if the`,
    `    URL already has a query string).`,
    ``,
    `IF YOU CANNOT CONFIRM A PART: set resolved=false with unresolvedReason and return parts: [].`,
    `An empty result is a correct answer. A guessed part number or invented link is not. Do not pad.`,
    ``,
    `Respond ONLY via the StructuredOutput tool.`,
  ].join('\n')
}

function verifyPrompt(t, part) {
  return [
    `You are a skeptical parts fact-checker. Someone will spend money based on this. DEFAULT TO REJECTING.`,
    ``,
    `VEHICLE: ${t.make} ${t.model} | years ${(t.years || []).join(', ') || '?'} | engines ${(t.engines || []).join(', ') || '?'}`,
    `ISSUE: ${t.title}`,
    `DOCUMENTED FIX: ${t.solution}`,
    ``,
    `PROPOSED PART:`,
    `  component: ${part.component}`,
    `  OEM part number: ${part.oemPartNumber || '(none given)'}`,
    `  aftermarket: ${(part.aftermarketXref || []).join(', ') || '(none)'}`,
    `  price: ${part.priceLow ?? '?'} - ${part.priceHigh ?? '?'} USD`,
    `  fitment basis claimed: ${part.fitmentBasis}`,
    `  note: ${part.note}`,
    `  buy links:`,
    ...(part.buyLinks || []).map((b) => `    [${b.linkType}] ${b.vendor} — ${b.url}`),
    ``,
    `Verify, using web search and by fetching the links:`,
    `  1. isCorrectComponentForFix — is this actually the part the documented fix calls for? A`,
    `     plausible-but-different component (e.g. a water pump when the fix names the thermostat`,
    `     housing) fails this check.`,
    `  2. fitmentConfirmed — does this part number genuinely fit THIS model, THESE years and THIS`,
    `     engine? Check a real catalogue. If the part number belongs to a different engine variant`,
    `     or generation, reject. If fitment cannot be confirmed, reject — do not assume.`,
    `  3. partNumberPlausible — does the number match this manufacturer's real numbering scheme, and`,
    `     does a search for it return this component? A fabricated number often looks right but`,
    `     returns nothing or something unrelated.`,
    `  4. linksAreRealProductPages — fetch each link. Does it load and actually carry this part?`,
    `     A 404, a generic search page with no results, or a page for a different part all fail.`,
    ``,
    `Return the four booleans, confidence 0-1, and a one-sentence reason naming what you checked`,
    `against. If anything is unverifiable, say so and mark it false.`,
  ].join('\n')
}

log(`Fix-parts resolver: ${TARGETS.length} published issues`)

const perIssue = await pipeline(
  TARGETS,
  (t) => agent(resolvePrompt(t), { label: `resolve:${t.make} ${t.model}`, phase: 'Resolve', schema: RESOLVE_SCHEMA })
    .then((r) => ({ t, parts: (r && r.resolved && Array.isArray(r.parts)) ? r.parts : [], unresolvedReason: r ? r.unresolvedReason : 'agent returned nothing' })),
  (res) => {
    const { t, parts } = res
    if (!parts.length) return { id: t.id, make: t.make, model: t.model, found: 0, parts: [], unresolvedReason: res.unresolvedReason }
    return parallel(parts.map((p) => () =>
      agent(verifyPrompt(t, p), { label: `verify:${t.make} ${p.component}`.slice(0, 60), phase: 'Verify', schema: VERDICT_SCHEMA })
        .then((v) => {
          if (!v) return null
          if (!v.fitmentConfirmed || !v.isCorrectComponentForFix || !v.linksAreRealProductPages) return null
          if (!v.partNumberPlausible && p.oemPartNumber) return null
          if ((v.confidence ?? 0) < 0.75) return null
          if (!Array.isArray(p.buyLinks) || !p.buyLinks.length) return null
          return {
            component: p.component,
            oemPartNumber: p.oemPartNumber || '',
            aftermarketXref: p.aftermarketXref || [],
            priceLow: p.priceLow ?? null,
            priceHigh: p.priceHigh ?? null,
            buyLinks: p.buyLinks,
            note: p.note,
            variants: [],
            verified: true,
            provenance: `fixparts-resolver: ${p.fitmentBasis} | verified: ${v.reason}`,
            _verdictConfidence: v.confidence,
          }
        })
    )).then((arr) => ({ id: t.id, make: t.make, model: t.model, title: t.title, found: parts.length, parts: arr.filter(Boolean) }))
  }
)

const resolvedIssues = []
let totalFound = 0, totalKept = 0
const unresolved = []
for (const r of perIssue.filter(Boolean)) {
  totalFound += r.found
  if (r.parts && r.parts.length) {
    totalKept += r.parts.length
    resolvedIssues.push({ id: r.id, make: r.make, model: r.model, title: r.title, fixParts: r.parts })
  } else {
    unresolved.push({ id: r.id, make: r.make, model: r.model, reason: r.unresolvedReason || 'all parts failed verification' })
  }
}

log(`issues resolved: ${resolvedIssues.length}/${TARGETS.length} | parts kept ${totalKept} of ${totalFound} proposed`)
for (const u of unresolved.slice(0, 15)) log(`unresolved: ${u.make} ${u.model} — ${String(u.reason).slice(0, 90)}`)

return { result: { resolvedIssues, unresolved, stats: { targets: TARGETS.length, resolvedIssues: resolvedIssues.length, partsProposed: totalFound, partsKept: totalKept } } }
